#!/usr/bin/env python3
"""Build one downloadable install.sh with the small Python implementation embedded."""
import base64
import gzip
import json
from pathlib import Path
import sys

root=Path(__file__).resolve().parents[1]
files=['command.sh',*[str(p.relative_to(root)) for p in sorted((root/'src').glob('*.py'))],
       *[str(p.relative_to(root)) for p in sorted((root/'examples').glob('*.example'))]]
payload=base64.b64encode(gzip.compress(json.dumps({name:(root/name).read_text() for name in files},sort_keys=True).encode(),mtime=0)).decode()
script='''#!/usr/bin/env bash
# Generated by tools/build-installer.py. Downloads need no repository checkout.
set -euo pipefail
if ! command -v python3 >/dev/null 2>&1; then
  printf 'Python 3 is required: sudo apt-get install python3\\n' >&2
  exit 1
fi
# Preserve the original terminal for the interactive child, despite this heredoc.
exec 3<&0
python3 - "$@" <<'PYTHON_BUNDLE'
import base64, gzip, json, os, pathlib, subprocess, sys, tempfile
payload="PAYLOAD"
with tempfile.TemporaryDirectory(prefix="infrastructure-installer-") as temporary:
    root=pathlib.Path(temporary)
    for name,content in json.loads(gzip.decompress(base64.b64decode(payload))).items():
        relative=pathlib.Path(name)
        if relative.is_absolute() or '..' in relative.parts:raise ValueError('Invalid embedded path')
        target=root/relative
        target.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
        target.write_text(content)
        target.chmod(0o600)
    with os.fdopen(os.dup(3)) as terminal:
        code=subprocess.call([sys.executable,str(root/'src/installer.py'),*sys.argv[1:]],stdin=terminal)
    sys.exit(code)
PYTHON_BUNDLE
'''.replace('PAYLOAD',payload)
target=Path(sys.argv[1]) if len(sys.argv)>1 else root/'install.sh'
target.write_text(script);target.chmod(0o755)
print('Built standalone installer: '+str(target))
